const current=document.body.dataset.page||'';
const nav=[['index.html','Home','home'],['about.html','About','about'],['membership.html','Membership','membership'],['directory.html','Directory','directory'],['events.html','Events','events'],['news.html','News','news'],['contact.html','Contact','contact']];
const header=document.querySelector('[data-header]');
if(header){header.className='topbar';header.innerHTML=`<div class="shell"><a class="wordmark" href="index.html" aria-label="SLIID home"><strong>SLIID</strong><span>Sri Lanka Institute of Interior Designers</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav" aria-label="Open navigation"><span></span><span></span><span></span></button><nav class="mainnav" id="site-nav" aria-label="Main navigation">${nav.map(([href,label,key])=>`<a href="${href}"${current===key?' aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="join-btn" href="membership.html">Join SLIID →</a></div>`}
const footer=document.querySelector('[data-footer]');
if(footer){footer.className='site-footer';footer.innerHTML=`<div class="shell"><div class="footer-grid"><div class="footer-mark"><a class="wordmark" href="index.html"><strong>SLIID</strong><span>Sri Lanka Institute of Interior Designers</span></a><div class="footer-tag">People · Spaces · A Better Sri Lanka</div></div><div class="footer-col"><b>Explore</b><a href="about.html">About</a><a href="membership.html">Membership</a><a href="directory.html">Directory</a><a href="events.html">Events</a><a href="news.html">News</a></div><div class="footer-col"><b>Resources</b><a href="governance.html">Governance</a><a href="education.html">Professional learning</a><a href="publications.html">Publications</a><a href="awards.html">Awards</a></div><div class="footer-col"><b>Connect</b><span>Colombo, Sri Lanka</span><a href="contact.html">Contact the Institute</a><a href="membership.html">Become a member</a></div></div><div class="copyright"><span>© ${new Date().getFullYear()} Sri Lanka Institute of Interior Designers. All rights reserved.</span><span>Established under Act No. 2 of 1998</span></div></div>`}
const menuButton=document.querySelector('.menu-toggle');const navigation=document.querySelector('#site-nav');if(menuButton&&navigation){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));navigation.classList.toggle('open',!open)})}
document.querySelectorAll('.form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const note=form.querySelector('.form-note');if(note)note.textContent='Thank you. Your enquiry is ready to be sent once the official SLIID email service is connected.';form.reset()}));
